@@ -0,0 +1,47 @@
+// bug-002 N3 · WB-1 · the header's Status is the status the API returned (inv-009 #3, I9). SellPolicy.tsx passes no
+// status to PageHeader, so the Sell header reads the kit's default "not in this screen's data" before and after a
+// sale; CancelPolicy.tsx passes none either, so Cancel's reads "not returned" while its policy read holds the status.
+//
+// On the live API (W1's support/api.ts, the node's port), each policy sold for the test through the API itself. Every
+// expected value is the exchange the page itself saw (watchApi), never a figure written here.
+import { expect, live, test } from '../W1/support/api';
+import { answered, daysFromToday, requestOf, route, sell, sellButton, sellForm, sellThroughApi, watchApi } from '../W1/support/workbench';
+import { openCancel } from '../W2/support/cancel';
+import { freshReference } from '../W3/support/fresh';
+import { headerField } from './support';
+
+test("WB-1 · before any answer the sell header's Status says nothing has been sold yet, never \"not in this screen's data\"", async ({ page, api }) => {
+  void api;
+  await page.goto(route.sell);
+  await expect(sellButton(page), 'setup: the sell form is shown').toBeVisible(live);
+  const status = headerField(page, 'Status');
+  await expect(status, 'setup: the sell header draws its Status field').toHaveCount(1);
+  await expect(status, "the Status gap is not the kit's default label").not.toContainText("not in this screen's data");
+  await expect(status, 'the Status says no sale has been made yet').toContainText(/nothing (has been )?sold yet/i);
+});
+
+test("WB-1 · after a 201 sale the sell header's Status reads the status the API returned", async ({ page, api }) => {
+  void api;
+  const seen = watchApi(page);
+  await sell(page, sellForm(freshReference('N3SS'), { amount: '617.43' }));
+  const sale = await answered(seen, 'POST', '/api/policies');
+  expect(sale.status, 'setup: the API sold the policy').toBe(201);
+  const returned = (sale.responseBody as { status: string }).status;
+  const status = headerField(page, 'Status');
+  await expect(status, "the Status field holds the 201's status").toContainText(returned, live);
+  await expect(status).not.toContainText("not in this screen's data");
+});
+
+test("WB-1 · the cancel header's Status reads the policy status the API holds", async ({ page, api }) => {
+  void api;
+  const reference = freshReference('N3CS');
+  await sellThroughApi(requestOf(sellForm(reference, { startDate: daysFromToday(10), amount: '628.14', paymentMethod: 'Card' })));
+  const seen = watchApi(page);
+  await openCancel(page, reference);
+  const read = await answered(seen, 'GET', `/api/policies/${reference}`);
+  expect(read.status, 'setup: the API read the policy').toBe(200);
+  const held = (read.responseBody as { status: string }).status;
+  const status = headerField(page, 'Status');
+  await expect(status, "the Status field holds the policy read's status").toContainText(held, live);
+  await expect(status, 'the Status is not drawn as missing').not.toContainText('not returned');
+});
diff --git a/tests/Uinsure.Policies.Web.Tests/unit/screens/support/cancel.tsx b/tests/Uinsure.Policies.Web.Tests/unit/screens/support/cancel.tsx
new file mode 100644
index 00000000..bf4780d3
--- /dev/null
+++ b/tests/Uinsure.Policies.Web.Tests/unit/screens/support/cancel.tsx
@@ -0,0 +1,59 @@
+// The cancel screen (src/Uinsure.Policies.Web/app/workbench/cancel/CancelPolicy.tsx) in jsdom, on the API's own answers
+// recorded in docs/ui/fixture/api/068-could-1-quote-then-cancel-for-the-same-date-agree-201.json: exchange 0 the sale
+// (its 201 body is the policy, read back as the GET 200 the screen asks for), 1 the quote, 2 the 201 cancel.
+import { screen } from '@testing-library/react';
+import userEvent from '@testing-library/user-event';
+import { vi } from 'vitest';
+import { notFound, recordedExchange, renderAppAt } from './app';
+
+const RECORDING = '068-could-1-quote-then-cancel-for-the-same-date-agree-201.json';
+export const soldPolicy = recordedExchange(RECORDING, 0).responseBody as { reference: string; status: string };
+export const quoted = recordedExchange(RECORDING, 1);
+export const cancelled = recordedExchange(RECORDING, 2);
+export const quotedDate = (quoted.responseBody as { cancellationDate: string }).cancellationDate;
+
+const json = (body: unknown, status: number): Response =>
+  new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json; charset=utf-8' } });
+
+/**
+ * The stub network. The policy read answers `reads[n]` for its nth call (the last one repeats): a Response, or 'reject'
+ * for a fetch that never reaches the API.
+ */
+export function stubCancel(reads: (Response | 'reject')[]): void {
+  let n = 0;
+  const base = `/api/policies/${soldPolicy.reference}`;
+  vi.stubGlobal('fetch', async (input: string) => {
+    const path = String(input);
+    if (path === base) {
+      const answer = reads[Math.min(n, reads.length - 1)];
+      n += 1;
+      if (answer === 'reject' || answer === undefined) throw new TypeError('Failed to fetch');
+      return answer.clone();
+    }
+    if (path.startsWith(`${base}/cancellation-quote`)) return json(quoted.responseBody, quoted.status);
+    if (path === `${base}/cancellation`) return json(cancelled.responseBody, cancelled.status);
+    return notFound();
+  });
+}
+
+/** The policy read the API gives for the sold policy: 200 and the policy. */
+export const policyRead = (): Response => json(soldPolicy, 200);
+
+/** A policy read the API refuses: a 503 problem. */
+export const policyReadRefused = (): Response =>
+  new Response(JSON.stringify({ status: 503, title: 'Service Unavailable' }), { status: 503, headers: { 'content-type': 'application/problem+json' } });
+
+/** Opens the cancel screen for the sold policy. */
+export function openCancel(): void {
+  renderAppAt(`workbench/policies/${soldPolicy.reference}/cancel`);
+}
+
+/** Quotes the recorded date, cancels on it and confirms; resolves once the 201 is drawn. */
+export async function quoteAndCancel(): Promise<void> {
+  const user = userEvent.setup();
+  await user.type(await screen.findByLabelText('Cancellation date'), quotedDate);
+  await user.click(screen.getByRole('button', { name: 'Quote this date' }));
+  await user.click(await screen.findByRole('button', { name: `Cancel on ${quotedDate}` }));
+  await user.click(await screen.findByRole('button', { name: `Cancel policy on ${quotedDate}` }));
+  await screen.findByText(new RegExp(`Cancelled on ${quotedDate}\\. The API answered ${cancelled.status}`));
+}
diff --git a/tests/Uinsure.Policies.Web.Tests/unit/screens/support/header.ts b/tests/Uinsure.Policies.Web.Tests/unit/screens/support/header.ts
new file mode 100644
